export const meta = {
  name: 'picrep-milestone-recon',
  description: 'Feasibility recon of top instHasPicScheme campaign milestones; rank by one-session landable value',
  phases: [
    { title: 'Recon', detail: 'deep-read each candidate milestone substrate' },
    { title: 'Judge', detail: 'rank by risk-adjusted one-session value' },
  ],
}

const ROOT = 'MainProjects/Algebraic-Jacobian-Challenge'
const AJ = `${ROOT}/AlgebraicJacobian`

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['milestone', 'verdict_score', 'one_session_landable', 'obligations', 'ready_bricks', 'missing_bricks', 'recommended_entry', 'risks', 'on_t15_critical_path', 'summary'],
  properties: {
    milestone: { type: 'string' },
    verdict_score: { type: 'number', description: '0-10 risk-adjusted one-session landable value' },
    one_session_landable: { type: 'string', enum: ['none', 'partial', 'substantial', 'full'], description: 'realistic fraction landable axiom-clean in one focused session' },
    obligations: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['name', 'difficulty', 'status'], properties: {
      name: { type: 'string' }, difficulty: { type: 'string', enum: ['S','M','L','XL'] }, status: { type: 'string', enum: ['ready','partial','missing'] } } } },
    ready_bricks: { type: 'array', items: { type: 'string' }, description: 'file:line — reusable proved substrate that directly feeds this milestone' },
    missing_bricks: { type: 'array', items: { type: 'string' }, description: 'brick — effort estimate; what is NOT in tree/Mathlib' },
    recommended_entry: { type: 'string', description: 'the concrete first Lean declaration/statement to write this session' },
    risks: { type: 'array', items: { type: 'string' } },
    on_t15_critical_path: { type: 'boolean' },
    summary: { type: 'string' },
  },
}

const common = `You are reconning ONE milestone of the instHasPicScheme (Picard-scheme representability) campaign in the Lean 4 (Mathlib v4.31) project at ${ROOT}. The full campaign plan is ${ROOT}/informal/pic-representability-campaign.md (read the relevant Part). Your job is a HONEST feasibility verdict for a single focused session: what exactly must be proved, what proved substrate already exists (verify by READING the actual Lean, not trusting docstrings — memory warns inherited "sorry-free" claims can be stale; use grep for genuine 'sorry' and read the decl bodies), what is genuinely missing from tree+Mathlib, and how much a strong prover could land AXIOM-CLEAN in one session. Be skeptical: flag false-as-pinned statements and universe/transparency walls. Do NOT write a whole proof; assess. Return the structured verdict. Use lean_hover/lean_goal via the LSP if helpful, and grep/Read freely (read-only recon; do not edit files).`

const candidates = [
  { key: 'B1-zariski-sheaf', label: 'B1', prompt: `MILESTONE B1 — picSharp is a Zariski sheaf + RigidifiedPic API (Kleiman lm:fff/idn/aut).
Target: build \`Picard/PicSharpZariskiSheaf.lean\` proving \`IsZariskiSheafOver (picSharp C)\` (predicate at ${AJ}/Picard/ZariskiDescentRepresentability.lean:103, note it is pinned at Scheme.{0}/Type 1) under [HasRationalPoint C], plus a RigidifiedPic structure (x0-rigidified representative exists/unique/automorphism-free).
Read: ${AJ}/Picard/RelPicFunctor.lean (relPresheaf :1057, relFunctorial :1004, relPicSetoid :582, relPicRel_of_iso :521, functorial :788); ${AJ}/Picard/SectionRingUniversal.lean (B0: globalSectionsAlgEquivBase, globalSectionsBaseChangeAlgEquiv, instHasTrivialConstants); ${AJ}/Picard/GlueDescent.lean (Modules.glue ~:106/:934); ${AJ}/Picard/FGAPicRepresentability.lean:139 (HasRationalPoint), :173 (picSharp). Assess: is the sheaf axiom for the RELATIVE Pic coset functor genuinely provable in one session, or is it a multi-session descent? What is automorphism-freeness's exact Lean obligation and does B0 suffice? Universe: picSharp is Type (u+1)-valued; IsZariskiSheafOver wants Type 1 — does this force u=0 and is that OK?` },
  { key: 'G2-scheme-side', label: 'G2ac', prompt: `MILESTONE G2(a)/(c) — finite Galois quotient SCHEME side (the algebraic heart G2(b) Speiser descent already LANDED).
Target: build \`Picard/FiniteGaloisQuotient.lean\`: \`galoisDescendScheme\` — given X' over k', Gal(k'/k) semilinear action, hypothesis EVERY FINITE ORBIT LIES IN AN AFFINE OPEN (never global P^N — Hironaka trap), produce X over k with Gamma-equivariant X ×_k k' ≅ X' and Hom_k(T,X) ≅ Hom_{k'}(T_{k'},X')^Gamma.
Read: ${AJ}/Picard/GaloisDescent/SemilinearModules.lean (LANDED: descentEquiv :361, descentMap_bijective :354, finrank_invariants :371, invariants :223, IsSemilinear :65 — the module-form Speiser brick G3 consumes). Then assess the SCHEME-side gluing: Mathlib Scheme.GlueData; RingTheory/Invariant/Basic.lean isInvariant_of_isGalois; how to build Spec(A^Gamma) glue and the Hom-set descent from the landed module descentEquiv. Is (a) orbit-in-affine gluing + (c) Hom-set one-session-landable? What's the affine heart (A = k' ⊗_k A^Gamma) and is it reachable from descentEquiv directly?` },
  { key: 'affine-serre-vanishing', label: 'P-root', prompt: `MILESTONE — affine Serre vanishing \`IsAffineHModuleVanishing\` (${AJ}/Cohomology/StructureSheafModuleK/Carriers.lean:222): for every affine open U and i>0, Subsingleton (HModule' k F i U). This is the residual of the ∀S HasCechToHModuleIso gate that blocks module_finite_hModule_one (genus finiteness) unconditionally, and unblocks T16 finrank_eq_genus/tangentSpaceIso.
Read: ${AJ}/Cohomology/StructureSheafModuleK/Carriers.lean (HModule/HModule' defs and context around :222); ${AJ}/Cohomology/StructureSheafModuleK.lean; ${AJ}/RiemannRoch/Adelic/CechComparisonGate.lean (the reduction, gate 4, isGrothendieckAbelian_moduleKSheaf :114, enoughInjectives :123, hasExt :130); ${AJ}/Cohomology/MayerVietorisCover.lean (HasCechToHModuleIso). Assess: what IS HModule' concretely (Ext-based? Čech?)? Is there ANY Mathlib backstop for affine cohomology vanishing of the ModuleCat k-flavour structure sheaf (grep Mathlib for Serre vanishing / cohomology of affine / higherCohomology)? Is a genuine one-session dent possible, or is this a from-scratch multi-session build? Give the honest verdict — do NOT be optimistic.` },
  { key: 'B3-rigid-pushforward', label: 'B3', prompt: `MILESTONE B3 — the rigid pushforward engine \`pushforward_locallyFree_of_h1_vanishing\` (hardest single lemma): A a f.g. k-algebra, q : C_A → Spec A, L invertible with h1 κ(t) (L_t)=0 at ALL scheme points t ⟹ q_*L locally free of rank χ(L_t), formation commutes with arbitrary A→A'. Corollary (h⁰≡1,χ≡1): q_*L invertible, canonical DivFamily. Route: push along finite C_A → P¹_A (base change of HasFiniteMapToP1) + Mumford AV II.5 two-term finite-free replacement on the 2-chart Čech complex of P¹_A.
Read the campaign doc Part II B3 + risk R1. Read: ${AJ}/RiemannRoch/Adelic/FiniteMapToP1.lean (HasFiniteMapToP1); ${AJ}/RiemannRoch/Adelic/ChiLedger.lean (the divisor H1/finrank machinery :160/:857); ${AJ}/RiemannRoch/Adelic/FinitenessP1.lean. Assess: does the tree have the finite-pushforward + two-term-complex substrate, or must it be built? Is the 'all scheme points' quantifier + arbitrary base change statable and one-session-scaffoldable behind a finiteness gate? Honest verdict on one-session landability (likely low — XL).` },
]

phase('Recon')
const verdicts = await parallel(candidates.map(c => () =>
  agent(`${common}\n\n${c.prompt}`, { label: `recon:${c.label}`, phase: 'Recon', schema: VERDICT_SCHEMA, model: 'sonnet', effort: 'high' })
))
const got = verdicts.filter(Boolean)

phase('Judge')
const judgment = await agent(
  `You are the judge selecting the single BEST milestone for a strong Lean prover to attack in ONE focused session, to make maximal genuine axiom-clean progress toward closing instHasPicScheme (the Picard-scheme representability endgame). Here are the recon verdicts (JSON):\n\n${JSON.stringify(got, null, 2)}\n\nWeigh: (a) probability of landing something GENUINELY verifiable and axiom-clean this session (a false-pinned or backstop-less XL that lands nothing is worse than a smaller sure thing); (b) leverage/unblocking toward instHasPicScheme; (c) whether the substrate is ready NOW. Prefer a milestone with a concrete recommended entry point and ready bricks. Output your ranked recommendation.`,
  { label: 'judge', phase: 'Judge', model: 'sonnet', effort: 'high', schema: {
    type: 'object', additionalProperties: false,
    required: ['ranking', 'winner', 'winner_rationale', 'winner_entry_point', 'session_plan'],
    properties: {
      ranking: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['milestone','score','one_line'], properties: { milestone: {type:'string'}, score: {type:'number'}, one_line: {type:'string'} } } },
      winner: { type: 'string' },
      winner_rationale: { type: 'string' },
      winner_entry_point: { type: 'string', description: 'the exact first Lean declaration to write' },
      session_plan: { type: 'array', items: { type: 'string' }, description: 'ordered concrete steps for the session' },
    },
  } }
)

return { verdicts: got, judgment }

